ROUTES=[]
def route(id,title,kind,scope,standard,sources,notes,nodes,edges):
    ROUTES.append(dict(id=id,title=title,kind=kind,scope=scope,standard=standard,sources=sources.split(),notes=notes,nodes=[dict(id=n[0],actor=n[1],action=n[2],group=n[3]) for n in nodes],edges=[dict(source=e[0],target=e[1],label=e[2] if len(e)>2 else '') for e in edges]))

