PALETTE={'municipal':('#E8F0FC','#376596'),'regional':('#EFE9FA','#7960A3'),'sector':('#E0F2EF','#297D77'),'evaluation':('#FFF0CE','#AD8425'),'private':('#EEF0F3','#687888'),'community':('#FBE9E0','#AA6243'),'decision':('#FFF0CE','#AD8425')}

def dot_text(r):
    lines=['digraph G {','graph [rankdir=TB, bgcolor="transparent", pad="0.15", nodesep="0.32", ranksep="0.20", splines=polyline, outputorder=edgesfirst];','node [shape=box, style="rounded,filled", fontname="DejaVu Sans", fontsize=17, margin="0.17,0.08", penwidth=1.3];','edge [fontname="DejaVu Sans", fontsize=14, color="#8091A4", fontcolor="#53647B", arrowsize=0.65, penwidth=1.2];']
    for n in r['nodes']:
        fill,stroke=PALETTE[n['group']]
        actor='<BR/>'.join(html.escape(x) for line in n['actor'].split('\n') for x in textwrap.wrap(line,27))
        action='<BR/>'.join(html.escape(x) for line in n['action'].split('\n') for x in textwrap.wrap(line,34))
        lab=f'<B>{actor}</B>'+ (f'<BR/>{action}' if action else '')
        shape='diamond' if n['group']=='decision' else 'box'
        lines.append(f'{n["id"]} [label=<{lab}>,shape={shape},fillcolor="{fill}",color="{stroke}",fontcolor="#172E47"];')
    for e in r['edges']:
        label=e['label'].replace('"','\\"')
        # El retorno de observaciones no altera el orden principal del proceso.
        back=next(i for i,n in enumerate(r['nodes']) if n['id']==e['target']) < next(i for i,n in enumerate(r['nodes']) if n['id']==e['source'])
        # Los retornos ya se explican en la caja y notas; abreviar etiquetas evita
        # que se superpongan a las de la secuencia principal. Se conserva el texto
        # íntegro de la transición en JSON, CSV y Mermaid.
        if back: label='sí' if label.startswith('sí') else ''
        else: label='\\n'.join(textwrap.wrap(label,19))
        extra=',constraint=false,style=dashed' if back else ''
        lines.append(f'{e["source"]} -> {e["target"]} [label="{label}"{extra}];')
    lines.append('}')
    return '\n'.join(lines)

def render_diagram(r):
    p=OUT/'diagramas'/r['id']
    p.with_suffix('.dot').write_text(dot_text(r))
    for ext in ('svg','pdf','png'):
        subprocess.run(['dot',f'-T{ext}',str(p.with_suffix('.dot')),'-o',str(p.with_suffix('.'+ext))],check=True)

if __name__=='__main__':
    import sys
    save_data()
    if '--sample' in sys.argv:
        render_diagram(ROUTES[1])
        print(OUT/'diagramas'/'R02.png')
    else:
        for r in COMMON+ROUTES: render_diagram(r)
        print('Diagramas:',len(COMMON)+len(ROUTES))
